# 通过int(input())获取输入数据的组数,然后遍历每一条输入数据
for _ in range(int(input())):
    # 接收当前的代码
    password = input()
    # 这个flag表示密码是否包含至少8位
    flag_8 = len(password) >= 8
    # 这个flag表示密码是否包含至少一个大写字母
    flag_upper = False
    for c in password:
        if c.isupper():
            flag_upper = True
    # 这个flag表示密码是否包含至少一个数字
    flag_digit = False
    for c in password:
        if c.isdigit():
            flag_digit = True
    if flag_8 and flag_upper and flag_digit:
        print("Y")
    else:
        print("N")
